import { useState, useRef, useEffect } from "react";

function App() {
  const [selectedCard, setSelectedCard] = useState(null);
  const [primeNumber, setPrimeNumber] = useState("");
  const [streamLogs, setStreamLogs] = useState([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const readerRef = useRef(null);
  const abortControllerRef = useRef(null);

  const questions = [
    {
      id: 1,
      title: "Prime Pattern Discovery",
      description: "Find the palindromic prime 123...i...321 where i is between 1000-3000",
      color: "from-purple-600 to-pink-600",
    },
    {
      id: 2,
      title: "Repunit Primes",
      description: "Find 5 primes of the form 111...1 (N ones) between N=2 and N=1040",
      color: "from-blue-600 to-cyan-600",
    },
    {
      id: 3,
      title: "Mersenne Primes",
      description: "Find primes of the form 2^p - 1 between p=2201 and p=2299",
      color: "from-green-600 to-emerald-600",
    },
    {
      id: 4,
      title: "Brocard's Conjecture",
      description: "Find 4 primes between squares of consecutive primes",
      color: "from-red-600 to-orange-600",
    },
    {
      id: 5,
      title: "Palindromic Primes",
      description: "Find a palindromic prime with at least 50 digits",
      color: "from-indigo-600 to-purple-600",
    },
    {
      id: 6,
      title: "Perfect Numbers",
      description: "Prove 2^(p-1)(2^p - 1) yields a perfect number using primes from Q3",
      color: "from-yellow-600 to-orange-600",
    },
    {
      id: 7,
      title: "Prime Conjectures",
      description: "Test famous prime conjectures on numbers with 50+ digits",
      color: "from-teal-600 to-green-600",
    },
  ];

  const startStream = async (endpoint) => {
    setIsStreaming(true);
    setStreamLogs([]);

    // Create new AbortController for this stream
    abortControllerRef.current = new AbortController();

    try {
      const response = await fetch(endpoint, {
        signal: abortControllerRef.current.signal
      });

      readerRef.current = response.body.getReader();
      const decoder = new TextDecoder();

      while (true) {
        const { done, value } = await readerRef.current.read();
        if (done) break;

        const chunk = decoder.decode(value);
        const lines = chunk.split('\n');

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            try {
              const data = JSON.parse(line.slice(6));
              setStreamLogs(prev => [...prev, data]);
            } catch (e) {
              // Skip malformed JSON
            }
          }
        }
      }
    } catch (error) {
      if (error.name !== 'AbortError') {
        setStreamLogs(prev => [...prev, { type: 'error', message: error.message }]);
      }
    } finally {
      setIsStreaming(false);
      readerRef.current = null;
      abortControllerRef.current = null;
    }
  };

  const stopStream = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    if (readerRef.current) {
      readerRef.current.cancel();
    }
    setIsStreaming(false);
  };

  const testPrimeStream = () => {
    if (!primeNumber.trim()) return;
    startStream(`http://localhost:8000/api/testprime/stream?n=${primeNumber}`);
  };

  const runQuestion1 = () => {
    startStream('http://localhost:8000/api/question1/stream');
  };

  const runQuestion2 = () => {
    startStream('http://localhost:8000/api/question2/stream');
  };

  const formatLogEntry = (log) => {
    switch (log.type) {
      case 'test':
        return `🎯 Round ${log.round}: Testing base ${log.base}, initial value: ${log.initial_value}`;
      case 'witness':
        if (log.result === 'composite') {
          return `❌ Base ${log.base} is a WITNESS (proves composite)`;
        } else {
          return `✅ Base ${log.base} passed (found ${log.value})`;
        }
      case 'square':
        return `  └─ Square ${log.iteration}: ${log.value}`;
      case 'small_prime_check':
        return log.result ? '✅ Found in small primes list' : '❌ Divisible by small prime';
      case 'small_prime_result':
        return log.result ? '✅ Found in small primes list' : '❌ Divisible by small prime';
      case 'result':
        return log.prime ? 
          `🎉 RESULT: ${log.reason}` : 
          `💥 RESULT: NOT PRIME (${log.reason})`;
      case 'checking':
        if (log.n !== undefined) {
          // Question 2 format
          return `🔍 Checking N=${log.n}, repunit=${log.number} (${log.length} digits)`;
        } else {
          // Question 1 format
          return `🔍 Checking i=${log.i}, number=${log.number} (${log.length} digits)`;
        }
      case 'found':
        if (log.n !== undefined) {
          // Question 2 format
          return `🏆 FOUND REPUNIT PRIME #${log.count}: N=${log.n}, number=${log.number} (via ${log.method})`;
        } else {
          // Question 1 format
          if (log.full_length) {
            return `🏆 FOUND PRIME: i=${log.i}, ${log.full_length} digit number: ${log.number} (via ${log.method})`;
          } else {
            return `🏆 FOUND PRIME: i=${log.i}, number=${log.number} (via ${log.method})`;
          }
        }
      case 'complete':
        if (log.primes) {
          const primesList = log.primes.map(([n, repr]) => `N=${n} (${repr})`).join(', ');
          return `🎊 COMPLETE: ${log.message} - Primes found: ${primesList}`;
        } else {
          return `🎊 COMPLETE: ${log.message}`;
        }
      case 'rejected':
        return `❌ Rejected: ${log.reason}`;
      case 'info':
        return `ℹ️ ${log.message}`;
      case 'error':
        return `❌ Error: ${log.message}`;
      default:
        return `📝 ${log.message || JSON.stringify(log)}`;
    }
  };

  if (selectedCard) {
    return (
      <div style={{
        minHeight: '100vh',
        background: 'linear-gradient(135deg, #1f2937 0%, #7c3aed 50%, #6b21a8 100%)',
        color: 'white',
        fontFamily: 'system-ui, -apple-system, sans-serif'
      }}>
        <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '2rem' }}>
          <button
            onClick={() => setSelectedCard(null)}
            style={{
              marginBottom: '1.5rem',
              display: 'flex',
              alignItems: 'center',
              color: '#c4b5fd',
              background: 'none',
              border: 'none',
              fontSize: '1rem',
              cursor: 'pointer',
              transition: 'color 0.3s ease'
            }}
            onMouseEnter={(e) => e.target.style.color = 'white'}
            onMouseLeave={(e) => e.target.style.color = '#c4b5fd'}
          >
            <span style={{ fontSize: '1.5rem', marginRight: '0.5rem' }}>←</span>
            Back to Dashboard
          </button>

          <div style={{
            background: 'rgba(255, 255, 255, 0.1)',
            backdropFilter: 'blur(10px)',
            borderRadius: '1.5rem',
            padding: '2rem',
            border: '1px solid rgba(255, 255, 255, 0.2)'
          }}>
            <h1 style={{
              fontSize: '2.5rem',
              fontWeight: 'bold',
              marginBottom: '1rem',
              background: 'linear-gradient(to right, #c084fc, #f472b6)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent'
            }}>
              Question {selectedCard.id}: {selectedCard.title}
            </h1>
            <p style={{ color: '#ddd6fe', fontSize: '1.125rem', marginBottom: '2rem' }}>
              {selectedCard.description}
            </p>

            {selectedCard.id === 1 && (
              <div style={{ marginBottom: '1.5rem' }}>
                <button
                  onClick={runQuestion1}
                  disabled={isStreaming}
                  style={{
                    padding: '0.75rem 1.5rem',
                    background: 'linear-gradient(to right, #9333ea, #ec4899)',
                    border: 'none',
                    borderRadius: '0.75rem',
                    fontWeight: '600',
                    color: 'white',
                    cursor: isStreaming ? 'not-allowed' : 'pointer',
                    opacity: isStreaming ? 0.5 : 1,
                    marginRight: '1rem',
                    transform: 'scale(1)',
                    transition: 'transform 0.2s ease'
                  }}
                  onMouseEnter={(e) => {
                    if (!isStreaming) e.target.style.transform = 'scale(1.05)';
                  }}
                  onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
                >
                  {isStreaming ? 'Running...' : 'Start Search'}
                </button>

                {isStreaming && (
                  <button
                    onClick={stopStream}
                    style={{
                      padding: '0.75rem 1.5rem',
                      background: 'linear-gradient(to right, #dc2626, #ea580c)',
                      border: 'none',
                      borderRadius: '0.75rem',
                      fontWeight: '600',
                      color: 'white',
                      cursor: 'pointer',
                      transform: 'scale(1)',
                      transition: 'transform 0.2s ease'
                    }}
                    onMouseEnter={(e) => e.target.style.transform = 'scale(1.05)'}
                    onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
                  >
                    Stop Search
                  </button>
                )}
              </div>
            )}

            {selectedCard.id === 2 && (
              <div style={{ marginBottom: '1.5rem' }}>
                <button
                  onClick={runQuestion2}
                  disabled={isStreaming}
                  style={{
                    padding: '0.75rem 1.5rem',
                    background: 'linear-gradient(to right, #2563eb, #06b6d4)',
                    border: 'none',
                    borderRadius: '0.75rem',
                    fontWeight: '600',
                    color: 'white',
                    cursor: isStreaming ? 'not-allowed' : 'pointer',
                    opacity: isStreaming ? 0.5 : 1,
                    marginRight: '1rem',
                    transform: 'scale(1)',
                    transition: 'transform 0.2s ease'
                  }}
                  onMouseEnter={(e) => {
                    if (!isStreaming) e.target.style.transform = 'scale(1.05)';
                  }}
                  onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
                >
                  {isStreaming ? 'Searching...' : 'Find Repunit Primes'}
                </button>

                {isStreaming && (
                  <button
                    onClick={stopStream}
                    style={{
                      padding: '0.75rem 1.5rem',
                      background: 'linear-gradient(to right, #dc2626, #ea580c)',
                      border: 'none',
                      borderRadius: '0.75rem',
                      fontWeight: '600',
                      color: 'white',
                      cursor: 'pointer',
                      transform: 'scale(1)',
                      transition: 'transform 0.2s ease'
                    }}
                    onMouseEnter={(e) => e.target.style.transform = 'scale(1.05)'}
                    onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
                  >
                    Stop Search
                  </button>
                )}
              </div>
            )}

            {streamLogs.length > 0 && (
              <div style={{ marginTop: '2rem' }}>
                <div style={{
                  background: 'rgba(0, 0, 0, 0.3)',
                  borderRadius: '1rem',
                  padding: '1.5rem',
                  border: '1px solid rgba(255, 255, 255, 0.1)'
                }}>
                  <div style={{ 
                    display: 'flex', 
                    justifyContent: 'space-between', 
                    alignItems: 'center', 
                    marginBottom: '1rem' 
                  }}>
                    <h3 style={{ fontSize: '1.25rem', fontWeight: '600' }}>Live Stream</h3>
                    {isStreaming && (
                      <div style={{ display: 'flex', alignItems: 'center' }}>
                        <div style={{
                          width: '0.75rem',
                          height: '0.75rem',
                          background: '#4ade80',
                          borderRadius: '50%',
                          marginRight: '0.5rem',
                          animation: 'pulse 2s infinite'
                        }}></div>
                        <span style={{ color: '#4ade80' }}>Streaming...</span>
                      </div>
                    )}
                  </div>
                  <div style={{
                    maxHeight: '24rem',
                    overflowY: 'auto',
                    fontFamily: 'monospace',
                    fontSize: '0.875rem'
                  }}>
                    {streamLogs.map((log, index) => (
                      <div key={index} style={{ color: '#d1d5db', marginBottom: '0.5rem' }}>
                        {formatLogEntry(log)}
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #1f2937 0%, #7c3aed 50%, #6b21a8 100%)',
      color: 'white',
      fontFamily: 'system-ui, -apple-system, sans-serif'
    }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '3rem 1.5rem' }}>
        {/* Header */}
        <div style={{ textAlign: 'center', marginBottom: '4rem' }}>
          <h1 style={{
            fontSize: '3.75rem',
            fontWeight: 'bold',
            marginBottom: '1.5rem',
            background: 'linear-gradient(to right, #c084fc, #f472b6, #06b6d4)',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent'
          }}>
            Prime Number Playground
          </h1>
          <p style={{
            fontSize: '1.25rem',
            color: '#ddd6fe',
            maxWidth: '48rem',
            margin: '0 auto'
          }}>
            Explore fascinating prime number problems with real-time Miller-Rabin testing and witness visualization
          </p>
        </div>

        {/* Prime Tester */}
        <div style={{ marginBottom: '4rem', maxWidth: '32rem', margin: '0 auto 4rem auto' }}>
          <div style={{
            background: 'rgba(255, 255, 255, 0.1)',
            backdropFilter: 'blur(10px)',
            borderRadius: '1.5rem',
            padding: '2rem',
            border: '1px solid rgba(255, 255, 255, 0.2)'
          }}>
            <h2 style={{ fontSize: '1.875rem', fontWeight: 'bold', marginBottom: '1.5rem', textAlign: 'center' }}>
              🧮 Prime Tester
            </h2>
            <div style={{ display: 'flex', gap: '1rem', marginBottom: '1.5rem' }}>
              <input
                type="text"
                placeholder="Enter a number to test..."
                value={primeNumber}
                onChange={(e) => setPrimeNumber(e.target.value)}
                style={{
                  flex: 1,
                  padding: '0.75rem 1rem',
                  background: 'rgba(255, 255, 255, 0.1)',
                  border: '1px solid rgba(255, 255, 255, 0.2)',
                  borderRadius: '0.75rem',
                  color: 'white',
                  fontSize: '1rem'
                }}
              />
              <button
                onClick={testPrimeStream}
                disabled={isStreaming || !primeNumber.trim()}
                style={{
                  padding: '0.75rem 1.5rem',
                  background: 'linear-gradient(to right, #0891b2, #1d4ed8)',
                  border: 'none',
                  borderRadius: '0.75rem',
                  fontWeight: '600',
                  color: 'white',
                  cursor: (isStreaming || !primeNumber.trim()) ? 'not-allowed' : 'pointer',
                  opacity: (isStreaming || !primeNumber.trim()) ? 0.5 : 1,
                  transform: 'scale(1)',
                  transition: 'transform 0.2s ease'
                }}
                onMouseEnter={(e) => {
                  if (!isStreaming && primeNumber.trim()) e.target.style.transform = 'scale(1.05)';
                }}
                onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
              >
                {isStreaming ? 'Testing...' : 'Test Prime'}
              </button>
            </div>

            {isStreaming && (
              <div style={{ marginBottom: '1.5rem', textAlign: 'center' }}>
                <button
                  onClick={stopStream}
                  style={{
                    padding: '0.5rem 1rem',
                    background: 'linear-gradient(to right, #dc2626, #ea580c)',
                    border: 'none',
                    borderRadius: '0.5rem',
                    fontWeight: '600',
                    color: 'white',
                    cursor: 'pointer',
                    fontSize: '0.875rem'
                  }}
                >
                  Stop Test
                </button>
              </div>
            )}

            {streamLogs.length > 0 && (
              <div style={{
                background: 'rgba(0, 0, 0, 0.3)',
                borderRadius: '1rem',
                padding: '1.5rem',
                border: '1px solid rgba(255, 255, 255, 0.1)'
              }}>
                <div style={{ 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  alignItems: 'center', 
                  marginBottom: '1rem' 
                }}>
                  <h3 style={{ fontSize: '1.25rem', fontWeight: '600' }}>Miller-Rabin Test Results</h3>
                  {isStreaming && (
                    <div style={{ display: 'flex', alignItems: 'center' }}>
                      <div style={{
                        width: '0.75rem',
                        height: '0.75rem',
                        background: '#4ade80',
                        borderRadius: '50%',
                        marginRight: '0.5rem',
                        animation: 'pulse 2s infinite'
                      }}></div>
                      <span style={{ color: '#4ade80' }}>Testing...</span>
                    </div>
                  )}
                </div>
                <div style={{
                  maxHeight: '16rem',
                  overflowY: 'auto',
                  fontFamily: 'monospace',
                  fontSize: '0.875rem'
                }}>
                  {streamLogs.map((log, index) => (
                    <div key={index} style={{ color: '#d1d5db', marginBottom: '0.5rem' }}>
                      {formatLogEntry(log)}
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Question Cards */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
          gap: '2rem'
        }}>
          {questions.map((question) => (
            <div
              key={question.id}
              onClick={() => setSelectedCard(question)}
              style={{
                cursor: 'pointer',
                transform: 'scale(1)',
                transition: 'transform 0.3s ease',
                background: `linear-gradient(135deg, ${question.color.includes('purple') ? '#9333ea, #ec4899' : 
                  question.color.includes('blue') ? '#2563eb, #06b6d4' :
                  question.color.includes('green') ? '#059669, #10b981' :
                  question.color.includes('red') ? '#dc2626, #f97316' :
                  question.color.includes('indigo') ? '#4f46e5, #9333ea' :
                  question.color.includes('yellow') ? '#d97706, #f97316' :
                  '#14b8a6, #10b981'})`,
                borderRadius: '1rem',
                padding: '1px'
              }}
              onMouseEnter={(e) => e.target.style.transform = 'scale(1.05)'}
              onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
            >
              <div style={{
                background: 'rgba(17, 24, 39, 0.8)',
                borderRadius: '1rem',
                padding: '1.5rem',
                height: '100%',
                backdropFilter: 'blur(10px)'
              }}>
                <div style={{ fontSize: '1.875rem', marginBottom: '1rem' }}>🔢</div>
                <h3 style={{ fontSize: '1.25rem', fontWeight: 'bold', marginBottom: '0.75rem' }}>
                  {question.title}
                </h3>
                <p style={{ 
                  color: '#d1d5db', 
                  fontSize: '0.875rem', 
                  lineHeight: '1.5',
                  marginBottom: '1rem'
                }}>
                  {question.description}
                </p>
                <div style={{ textAlign: 'right' }}>
                  <span style={{ 
                    fontSize: '1.5rem', 
                    opacity: 0.5,
                    transition: 'opacity 0.3s ease'
                  }}>
                    →
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Add CSS animation for pulse effect */}
      <style jsx>{`
        @keyframes pulse {
          0%, 100% {
            opacity: 1;
          }
          50% {
            opacity: 0.5;
          }
        }
      `}</style>
    </div>
  );
}

export default App;
